df[STATUS_COL] = pd.to_numeric(df[STATUS_COL], errors="coerce").fillna(0).astype(np.int64)
for c in COVARIATE_COLS:
    df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0).astype(np.int64)

